<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue';
import {Head,Link,router,usePage} from '@inertiajs/vue3';import axios from 'axios';import {crew,modes} from '../art';import Feedback from '../Components/Feedback.vue';
import SaveNotice from '../Components/SaveNotice.vue';import {useStudyDelivery} from '../useStudyDelivery';import {answerKey} from '../studyDelivery';
const props=defineProps({attempt:Object,bookmarks:Array});const page=usePage(),data=ref(props.attempt),index=ref(0),clock=ref(Date.now()),offset=new Date(props.attempt.server_now).getTime()-Date.now();
const q=computed(()=>data.value.items[index.value]),ended=computed(()=>data.value.status!=='active');
const remaining=computed(()=>data.value.deadline?Math.max(0,Math.ceil((new Date(data.value.deadline).getTime()-clock.value-offset)/1000)):null);
const timer=computed(()=>remaining.value===null?'Untimed':Math.floor(remaining.value/60)+':'+String(remaining.value%60).padStart(2,'0'));
function accept(r){data.value=r.data.attempt;page.props.achievement=r.data.achievement;page.props.community=r.data.community;const at=data.value.items.findIndex(i=>i.item_id===pending.value?.payload.item_id);if(at>=0)index.value=at}
const {pending,busy,error,status,send,retry,discard}=useStudyDelivery('sushi:pending:'+page.props.user.id+':attempt:'+data.value.id,'/attempts/'+data.value.id,accept);
let interval,heartbeat,lastAction=Date.now(),finishing=false;
function touch(){lastAction=Date.now()}
function save(answer,check=false){if(ended.value||q.value.checked)return;return send('answer',{item_id:q.value.item_id,answer,check,revision:data.value.revision,request_token:crypto.randomUUID()})}
function reload(){discard();router.reload()}
function finish(){if(finishing||busy.value)return;finishing=true;router.post('/attempts/'+data.value.id+'/finish',{}, {onFinish:()=>{finishing=false;data.value=page.props.attempt}})}
function keys(e){const key=answerKey(e);if(key&&key<=4&&!busy.value&&!pending.value&&!ended.value&&!q.value.checked){e.preventDefault();save(String.fromCharCode(64+key))}}
onMounted(()=>{window.addEventListener('pointerdown',touch);window.addEventListener('keydown',touch);window.addEventListener('keydown',keys);interval=setInterval(()=>{clock.value=Date.now();if(remaining.value===0&&!ended.value&&!busy.value)finish()},1000);heartbeat=setInterval(()=>{if(!document.hidden&&!ended.value)axios.post('/attempts/'+data.value.id+'/heartbeat',{active:Date.now()-lastAction<60000}).catch(()=>{})},15000)});
onUnmounted(()=>{clearInterval(interval);clearInterval(heartbeat);window.removeEventListener('pointerdown',touch);window.removeEventListener('keydown',touch);window.removeEventListener('keydown',keys)});
</script><template><Head :title="modes[data.mode]"/><div class="page-title"><div><p class="eyebrow">{{modes[data.mode]}} · {{data.status.replace('_',' ')}}</p><h1>{{ended?'Round complete':'Question '+(index+1)+' of '+data.items.length}}</h1><p v-if="ended">{{data.score}} / {{data.items.length}} correct · {{Math.round(data.score/data.items.length*100)}}%</p></div><strong class="timer">{{ended?'Finished':timer}}</strong></div>
<section v-if="ended&&data.mode==='fresh'" class="notice"><strong>🍣 Catch complete. Your study progress is saved.</strong><p>{{page.props.community?.habits.current}} study-day streak · {{page.props.community?.badge_count}} Passport stamps</p><Link class="button" href="/flashcards">Keep rolling with Memory Maki</Link> <Link href="/passport">See achievements</Link></section>
<SaveNotice :status="status" :error="error" :pending="pending" :busy="busy" @retry="retry" @reload="reload"/><p class="muted keyboard-hint">Keyboard: A–D or 1–4 selects an answer when focus is outside a control.</p>
<div class="question-nav" aria-label="Question navigator"><button v-for="(item,i) in data.items" :key="item.item_id" :disabled="busy||!!pending" :class="{selected:i===index,answered:item.answer}" @click="index=i" :aria-label="'Question '+(i+1)">{{i+1}}</button></div>
<article class="panel"><div class="row"><div class="subject-line"><img class="small-portrait" :src="crew[q.subject]?.image" :alt="crew[q.subject]?.name"><div><strong>{{q.subject}}</strong><small>{{q.topic}} · {{q.tier}} · {{q.id}}</small></div></div><button class="plain" @click="router.post('/bookmarks/'+q.id,{bookmarked:!bookmarks.includes(q.id)},{preserveScroll:true,onSuccess:()=>data=page.props.attempt})">{{bookmarks.includes(q.id)?'★ Saved':'☆ Save'}}</button></div>
<h2 class="pre question-stem">{{q.stem}}</h2><div class="options"><button v-for="(option,i) in q.options" :key="i" :disabled="busy||pending||ended||q.checked" :class="{selected:q.answer===String.fromCharCode(65+i),correct:q.key===String.fromCharCode(65+i)}" @click="save(String.fromCharCode(65+i))"><strong>{{String.fromCharCode(65+i)}}.</strong> {{option}}</button></div>
<button v-if="!ended&&!q.checked&&['fresh','tutor'].includes(data.mode)" class="primary" :disabled="busy||pending||!q.answer" @click="save(q.answer,true)">Check answer</button><Feedback :question="q"/><p v-if="ended&&!q.key" class="notice">Your administrator has not released the answer explanations yet.</p>
<div class="row spaced study-controls"><button :disabled="index===0||busy||pending" @click="index--">Previous</button><button :disabled="index===data.items.length-1||busy||pending" @click="index++">Next</button></div></article>
<details v-if="!ended" class="panel"><summary>Finish this round</summary><p>{{data.mode==='fresh'?'Answer all ten questions to earn today’s stamp.':'Submit your saved answers. Unanswered questions count as incorrect in the set score.'}}</p><button class="primary" :disabled="busy||pending" @click="finish">Submit round</button></details>
</template>
